import base64
import gzip
from pathlib import Path


FILES = {
    "docs/research/C09-R2.md": "",
    "docs/research/fixtures/c09-r2-corpus.mjs": "",
    "docs/research/fixtures/c09-r2-validate-ast.mjs": "",
    ".github/scripts/c09-r2-generate-ast.mjs": ""
}


for path, encoded in FILES.items():
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(encoded)))
